insert into public.medical_records (class_id, id, data) values
  ('00000000-0000-0000-0000-000000000001', 'MR001', '{"id":"MR001","regId":"REG001","noRM":"000001","anamnesis":"Pasien datang dengan keluhan pusing berputar, tengkuk terasa berat sejak 2 hari yang lalu. Mual (+), muntah (-). Riwayat tekanan darah tinggi tidak terkontrol.","physicalExam":"Keadaan Umum: Sedang, Kesadaran: Compos Mentis. TD: 160/100 mmHg, Nadi: 88 x/menit, RR: 20 x/menit, Suhu: 36.8 C, SpO2: 98%. Cor/Pulmo dalam batas normal.","diagnosis":"I10 - Hipertensi Esensial (Primer)","diagnosisStatus":"Verified","doctorId":"U002","date":"2026-08-28"}'::jsonb),
  ('00000000-0000-0000-0000-000000000001', 'MR006', '{"id":"MR006","regId":"REG006","noRM":"000001","anamnesis":"Pasien datang untuk kontrol rutin hipertensi bulanan dan keluhan tengkuk terasa kaku ringan setelah beraktivitas. Pusing (-), mual (-).","physicalExam":"KU: Baik, Kesadaran: Compos Mentis. TD: 140/90 mmHg, Nadi: 80 x/menit reguler, RR: 18 x/menit, Suhu: 36.6 C, SpO2: 99%. JVP tidak meningkat, bising jantung (-).","diagnosis":"I10 - Hipertensi Esensial Stage 1 & E78.5 - Dislipidemia Campuran","diagnosisStatus":"Verified","doctorId":"U002","date":"2026-09-11"}'::jsonb),
  ('00000000-0000-0000-0000-000000000001', 'MR002', '{"id":"MR002","regId":"REG002","noRM":"000002","anamnesis":"Nyeri dada kiri menjalar ke bahu kiri sejak 3 jam SMRS. Rasa seperti tertindih beban berat, keringat dingin (+), sesak nafas (+).","physicalExam":"KU: Lemah, Kesadaran: CM. TD: 140/90 mmHg, Nadi: 96 x/m, RR: 24 x/m, Suhu: 37.0 C, SpO2: 96%. EKG: ST deviasi di lead V1-V4.","diagnosis":"I25.1 - Penyakit Jantung Iskemik","diagnosisStatus":"Verified","doctorId":"U002","date":"2026-08-29"}'::jsonb),
  ('00000000-0000-0000-0000-000000000001', 'MR007', '{"id":"MR007","regId":"REG007","noRM":"000002","anamnesis":"Kontrol rutin pasca rawat inap jantung 2 minggu lalu. Nyeri dada terkontrol, sesak saat istirahat (-), aktivitas ringan mandiri baik.","physicalExam":"KU: Sedang, Kesadaran: Compos Mentis. TD: 125/80 mmHg, Nadi: 76 x/menit, RR: 18 x/menit, Suhu: 36.5 C, SpO2: 99%. S1-S2 murni, murmur (-).","diagnosis":"I25.1 - Penyakit Jantung Iskemik Kronik (CAD Post NSTEMI) & I10 - Hipertensi Terkontrol","diagnosisStatus":"Verified","doctorId":"U002","date":"2026-09-11"}'::jsonb),
  ('00000000-0000-0000-0000-000000000001', 'MR003', '{"id":"MR003","regId":"REG003","noRM":"000003","anamnesis":"Kontrol rutin penyakit jantung, mengeluh cepat lelah jika beraktivitas berat.","physicalExam":"TD: 130/80 mmHg, Nadi: 76 x/m, RR: 18 x/m, Suhu: 36.5 C. Murmur (-), Gallop (-).","diagnosis":"I25.1 - Penyakit Jantung Iskemik","diagnosisStatus":"Verified","doctorId":"U002","date":"2026-08-30"}'::jsonb);
insert into public.cppt (class_id, id, data) values
  ('00000000-0000-0000-0000-000000000001', 'CPPT001', '{"id":"CPPT001","mrId":"MR001","regId":"REG001","date":"2026-08-28","time":"10:30","subjective":"Pasien masih merasa pusing berkurang setelah istirahat.","objective":"TD: 145/90 mmHg, N: 82x/m, RR: 18x/m, S: 36.6 C.","assessment":"Hipertensi stage 2 terkontrol sebagian.","plan":"Amlodipine 10mg 1x1 tab PO malam. Observasi tanda vital tiap 4 jam. Edukasi diet rendah garam.","doctorId":"U002","nurseId":"U003","profession":"Dokter Spesialis Penyakit Dalam","staffName":"dr. Sari Dewi, Sp.PD","unit":"IGD","verified":true,"vitalSigns":{"systolic":"145","diastolic":"90","heartRate":"82","respRate":"18","temp":"36.6","spo2":"98"}}'::jsonb),
  ('00000000-0000-0000-0000-000000000001', 'CPPT002', '{"id":"CPPT002","mrId":"MR002","regId":"REG002","date":"2026-08-29","time":"14:00","subjective":"Nyeri dada berkurang dengan pemberian ISDN sublingual.","objective":"TD: 130/85 mmHg, N: 84x/m, SpO2: 98% on nasal kanul 3 lpm.","assessment":"NSTEMI Teratasi, CAD 2VD.","plan":"Lanjut Clopidogrel 75mg 1x1, Atorvastatin 20mg 1x1, Rawat VVIP.","doctorId":"U002","nurseId":"U003","profession":"Dokter Spesialis Kardiologi","staffName":"dr. Sari Dewi, Sp.PD","unit":"Rawat Inap","verified":true,"vitalSigns":{"systolic":"130","diastolic":"85","heartRate":"84","respRate":"20","temp":"36.7","spo2":"98"}}'::jsonb),
  ('00000000-0000-0000-0000-000000000001', 'CPPT006', '{"id":"CPPT006","mrId":"MR006","regId":"REG006","date":"2026-09-11","time":"09:45","subjective":"Pasien datang untuk kontrol rutin tensi bulanan. Mengeluh tengkuk agak tegang terutama sore hari, riwayat minum obat rutin Amlodipine.","objective":"KU: Baik, Kesadaran: CM. TD: 140/90 mmHg, HR: 80x/m reguler, RR: 18x/m, Suhu: 36.6 C, SpO2: 99%. Suara nafas vesikuler, edema tungkai (-).","assessment":"Hipertensi Esensial Stage 1 Terkontrol Sebagian & Dislipidemia Campuran.","plan":"1. Amlodipine 10mg 1x1 tab PO malam. 2. Atorvastatin 20mg 1x1 tab PO malam. 3. Tindakan: Rekam Elektrokardiogram (EKG 12-Lead) & Cek Profil Lipid Darah Lengkap. 4. Edukasi pola diet rendah garam & olahraga aerobik teratur.","doctorId":"U002","nurseId":"U003","profession":"Dokter Spesialis Penyakit Dalam","staffName":"dr. Sari Dewi, Sp.PD","unit":"Poli Penyakit Dalam","verified":true,"vitalSigns":{"systolic":"140","diastolic":"90","heartRate":"80","respRate":"18","temp":"36.6","spo2":"99"}}'::jsonb),
  ('00000000-0000-0000-0000-000000000001', 'CPPT007', '{"id":"CPPT007","mrId":"MR007","regId":"REG007","date":"2026-09-11","time":"10:15","subjective":"Pasien kontrol berkala pasca perawatan NSTEMI. Nyeri dada (-) saat istirahat, keluhan sesak nafas berkurang signifikan.","objective":"KU: Sedang, CM. TD: 125/80 mmHg, HR: 76x/m kuat angkat, RR: 18x/m, Suhu: 36.5 C, SpO2: 99%. Jantung S1-S2 normal, murmur (-), gallop (-).","assessment":"Penyakit Jantung Iskemik Kronik (CAD Post NSTEMI Stabil) & Hipertensi Terkontrol.","plan":"1. Clopidogrel 75mg 1x1 tab PO. 2. Bisoprolol 2.5mg 1x1 tab PO pagi. 3. Tindakan Medis: Pemeriksaan Echocardiography berkala & Rekam EKG Evaluasi. 4. Kontrol ulang 1 bulan.","doctorId":"U002","nurseId":"U003","profession":"Dokter Spesialis Kardiologi","staffName":"dr. Sari Dewi, Sp.PD","unit":"Poli Jantung & Pembuluh Darah","verified":true,"vitalSigns":{"systolic":"125","diastolic":"80","heartRate":"76","respRate":"18","temp":"36.5","spo2":"99"}}'::jsonb);
